s=s.replace('canManage&&<Button type="link" onClick={()=>moveSlot(r)}>{r.state===\'OPEN\'?\'关闭\':\'开放\'}</Button>', 'canManage&&r.state!==\'CANCELLED\'&&<Space wrap><Button type="link" onClick={()=>moveSlot(r)}>{r.state===\'OPEN\'?\'关闭\':\'开放\'}</Button>{new Date(r.startsAt)>new Date()&&<><Button type="link" onClick={()=>setScheduleChange({row:r,cancel:false})}>延期</Button><Button type="link" danger onClick={()=>setScheduleChange({row:r,cancel:true})}>取消时段</Button></>}</Space>')
