p=Path('apps/admin/src/pages/events/Sessions.tsx')
s=p.read_text(encoding='utf-8').replace("import { api } from '@/api';", "import { api } from '@/api';\nimport BookingScheduleChange from '@/components/BookingScheduleChange';")
s=s.replace('checkedAttendees:number[]','schedulePending:boolean;checkedAttendees:number[]')
