s=s.replace("r.state==='OPEN'?'开放报名':'已关闭'", "({OPEN:'开放报名',CLOSED:'已关闭',CANCELLED:'已取消'} as Record<string,string>)[r.state]??r.state")
s=s.replace('access.canEventsEdit&&<Button type="link" onClick={()=>toggle(r)}>{r.state===\'OPEN\'?\'关闭报名\':\'开放报名\'}</Button>', 'access.canEventsEdit&&r.state!==\'CANCELLED\'&&<Space wrap><Button type="link" onClick={()=>toggle(r)}>{r.state===\'OPEN\'?\'关闭报名\':\'开放报名\'}</Button>{new Date(r.startsAt)>new Date()&&<><Button type="link" onClick={()=>setScheduleChange({row:r,cancel:false})}>延期</Button><Button type="link" danger onClick={()=>setScheduleChange({row:r,cancel:true})}>取消场次</Button></>}</Space>')
s=s.replace("({CONFIRMED:'已确认'", "r.schedulePending?'待学员确认改期':({CONFIRMED:'已确认'")
s=s.replace("r.state==='CONFIRMED'?<Space", "r.state==='CONFIRMED'&&!r.schedulePending?<Space")
s=s.replace('</Form></Modal></>;', '</Form></Modal><BookingScheduleChange selection={scheduleChange} base="/admin/events/sessions" onClose={()=>setScheduleChange(undefined)} onSaved={()=>{table.current?.reload();registrations.current?.reload();}}/></>;')
