p=Path('apps/mobile/lib/bookings.ts')
s=p.read_text(encoding='utf-8').replace('checkedCount:number}', 'checkedCount:number;originalStartsAt:string;originalEndsAt:string;changeReason:string|null;scheduleVersion:number;schedulePending:boolean}')
p.write_text(s,encoding='utf-8')
p=Path('apps/mobile/pages/booking/mine.uvue')
s=p.read_text(encoding='utf-8')
s=s.replace('{{bookingStates[b.state]??b.state}}', "{{b.schedulePending?'待确认新安排':(bookingStates[b.state]??b.state)}}")
s=s.replace('<text v-if="b.state===\'CONFIRMED\'" class="meta">取消截止', '''<view v-if="b.changeReason" class="schedule-change"><text v-if="b.originalStartsAt!==b.startsAt" class="meta">原安排：{{formatChinaTime(b.originalStartsAt)}}</text><text class="body-copy" :user-select="true">{{b.changeReason}}</text><text v-if="b.schedulePending" class="meta">请确认新安排；如不方便参加，可在新开始前取消。</text></view><text v-if="b.state==='CONFIRMED'" class="meta">取消截止''')
s=s.replace('<button v-if="b.canCancel', '<button v-if="b.schedulePending&&new Date(b.startsAt).getTime()>serverNow" class="primary-button schedule-accept" :disabled="busy" @click="accept(b)">确认新安排</button><button v-if="b.canCancel')
s=s.replace('function cancel(b:Booking)', '''function accept(b:Booking){uni.showModal({title:'确认新安排',content:formatChinaTime(b.startsAt)+'\\n'+b.location,confirmText:'确认参加',success:async r=>{if(!r.confirm||busy.value)return;busy.value=true;try{await request('/me/bookings/'+(b.kind==='appointment'?'appointments':'registrations')+'/'+b.id+'/accept-schedule',{method:'POST',data:{expectedScheduleVersion:b.scheduleVersion}});uni.showToast({title:'已确认新安排',icon:'none'});reload();}catch(e){uni.showToast({title:(e as Error).message,icon:'none'});reload();}finally{busy.value=false;}}});}
function cancel(b:Booking)''')
s=s.replace('</style>', '.schedule-change{padding:12px;background-color:#F3F0E8;border-left:2px solid #8B7350;margin:12px 0;}.schedule-accept{margin-top:14px;font-size:14px;}</style>')
p.write_text(s,encoding='utf-8')
